/// Finds well-known Ice objects registered with the IceGrid registry.
public protocol Query {
    /// Finds a well-known object by identity.
    ///
    /// - Parameters:
    ///   - id: The identity.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: A proxy to the well-known object, or null if no such object is registered.
    func findObjectById(id: Ice.Identity, current: Ice.Current) async throws -> Ice.ObjectPrx?

    /// Finds a well-known object by type. If there are several objects registered for the given type, the object is
    /// randomly selected.
    ///
    /// - Parameters:
    ///   - type: The object type.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: A proxy to a well-known object with the specified type, or null if no such object is registered.
    func findObjectByType(type: Swift.String, current: Ice.Current) async throws -> Ice.ObjectPrx?

    /// Finds a well-known object by type on the least-loaded node. If the registry does not know which node hosts
    /// the object (for example, because the object was registered with a direct proxy), the registry assumes the
    /// object is hosted on a node that has a load average of 1.0.
    ///
    /// - Parameters:
    ///   - type: The object type.
    ///   - sample: The sampling interval.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: A proxy to the well-known object, or null if no such object is registered.
    func findObjectByTypeOnLeastLoadedNode(type: Swift.String, sample: LoadSample, current: Ice.Current) async throws -> Ice.ObjectPrx?

    /// Finds all the well-known objects with the given type.
    ///
    /// - Parameters:
    ///   - type: The object type.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: A list of proxies to the well-known objects with the specified type. Can be empty.
    func findAllObjectsByType(type: Swift.String, current: Ice.Current) async throws -> Ice.ObjectProxySeq

    /// Finds all the replicas of a well-known object.
    ///
    /// - Parameters:
    ///   - proxy: A proxy that identifies the well-known object.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: A list of proxies  to the replicas of the well-known object specified by @p proxy. Can be empty.
    func findAllReplicas(proxy: Ice.ObjectPrx?, current: Ice.Current) async throws -> Ice.ObjectProxySeq
}


